import { createFileRoute, Link } from "@tanstack/react-router"

import { InstrumentDetail } from "@/components/instrument-detail"
import { buttonVariants } from "@/components/ui/button"
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyTitle,
} from "@/components/ui/empty"
